parameters.query:
SELECT (COALESCE((SELECT jsonb_object_agg(key, value) FROM config), '{}'::jsonb)
     || COALESCE((SELECT jsonb_object_agg(key, to_jsonb(value)) FROM secrets), '{}'::jsonb)
       ) AS cfg;

parameters.jsCode:
// ===== CONFIG FROM DB (table: config) =====
// Reads the aggregated config object produced by the 'Load Config (DB)' node.
// Original hardcoded values now live in Postgres (see schema.sql), editable
// via pconfig.html. Downstream nodes read $('Load Config').first().json.* as before.
const cfg = $input.first().json.cfg || {};

// derive openreviewVenues from orConfs x [thisYear, lastYear] (as the old node did)
const _y = new Date().getFullYear();
const _confs = cfg.orConfs || ["ICML", "ICLR", "NeurIPS"];
const openreviewVenues = [];
for (const y of [_y, _y - 1]) {
  for (const c of _confs) openreviewVenues.push(`${c}.cc/${y}/Conference`);
}

return [{ json: {
  keywordQuery:      cfg.keywordQuery,
  fields:            cfg.fields,
  KEYWORD_MIN_SCORE: cfg.KEYWORD_MIN_SCORE,
  AUTHOR_MIN_SCORE:  cfg.AUTHOR_MIN_SCORE,
  daysBack:          cfg.daysBack,
  venueWhitelist:    cfg.venueWhitelist,
  authors:           cfg.authors,
  openreviewVenues,
  // secrets (read live from DB, used by SS/LLM/Discord nodes)
  SS_API_KEY:      cfg.SS_API_KEY,
  LLM_PROVIDER:    cfg.LLM_PROVIDER,
  LLM_BASE_URL:    cfg.LLM_BASE_URL,
  LLM_API_KEY:     cfg.LLM_API_KEY,
  LLM_MODEL:       cfg.LLM_MODEL,
  DISCORD_WEBHOOK: cfg.DISCORD_WEBHOOK
} }];

// ss_id is filled manually in config -> pass straight through. No resolver.
return ($json.authors || []).map(a => {
  const name = (a.name || '').trim();
  return { json: {
    name,
    topic: (a.topic || '').trim() || 'other',
    arxiv_name: (a.arxiv_name || '').trim() || name,
    ss_id: (a.ss_id || '').trim()
  }};
});

// parse Atom XML from arXiv into normalized papers
const xml = $input.first().json.data || $input.first().json.body || $input.first().binary || "";
const raw = typeof xml === "string" ? xml : ($input.first().json.data || "");
const text = raw;
const entries = text.split("<entry>").slice(1);
const out = [];
for (const e of entries) {
  const g = (tag) => { const m = e.match(new RegExp("<"+tag+"[^>]*>([\\s\\S]*?)</"+tag+">")); return m ? m[1].trim() : ""; };
  const idUrl = g("id");
  const m = idUrl.match(/abs\/([^v]+)(v\d+)?/);
  const arxiv = m ? m[1] : null;
  const doiM = e.match(/<arxiv:doi[^>]*>([\s\S]*?)<\/arxiv:doi>/);
  const doi = doiM ? doiM[1].trim() : null;
  const title = g("title").replace(/\s+/g," ");
  const abstract = g("summary").replace(/\s+/g," ");
  const pub = g("published").slice(0,10);
  const names = [...e.matchAll(/<name>([\s\S]*?)<\/name>/g)].map(x=>x[1].trim());
  const pdf = arxiv ? `https://arxiv.org/pdf/${arxiv}` : null;
  const dedup_key = arxiv ? `arxiv:${arxiv}` : (doi ? `doi:${doi}` : `arxivurl:${idUrl}`);
  out.push({ json: {
    dedup_key, arxiv_id:arxiv, doi, semantic_scholar_id:null,
    title, authors:names.join(", "), abstract, url:idUrl, pdf_url:pdf,
    published_at:pub, venue:"arXiv", source:"arxiv_keyword", min_score:7
  }});
}
return out;

// Run Once for All Items: iterate every SS response (one per author).
const minScore = $('Load Config').first().json.AUTHOR_MIN_SCORE;
const authorsIn = $('SS Author Papers').all();  // same order as input
const out = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  const a = (authorsIn[i] && authorsIn[i].json) || {};
  const wantName = a.name || '';
  const items = inputs[i].json.data || [];
  for (const p of items) {
    if (!p.title) continue;
    const arxiv = p.externalIds?.ArXiv || null;
    const doi = p.externalIds?.DOI || null;
    const dedup_key = arxiv ? `arxiv:${arxiv}` : doi ? `doi:${doi}` : `ss:${p.paperId}`;
    out.push({ json: {
      dedup_key, arxiv_id:arxiv, doi, semantic_scholar_id:p.paperId,
      title:p.title, authors:(p.authors||[]).map(x=>x.name).join(", "),
      abstract:p.abstract||p.tldr?.text||"", url:p.url, pdf_url:p.openAccessPdf?.url||null,
      published_at:p.publicationDate, venue:p.venue||"",
      source:`ss_author:${wantName||'unknown'}`, min_score:minScore
    }});
  }
}
return out;

// Run Once for All Items. Author name is parsed from each feed's own <title>
// (search_query=au:"NAME" ...), so verification never depends on index alignment.
const minScore = $('Load Config').first().json.AUTHOR_MIN_SCORE;
function norm(s){return (s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/[^a-z\s]/g,' ').replace(/\s+/g,' ').trim();}

const out = [];
for (const it of $input.all()) {
  const text = it.json.data || "";
  // pull the queried author name out of the feed title
  const qm = text.match(/search_query=au:(?:%22|")([^"%]+)(?:%22|")/i);
  const wantName = qm ? decodeURIComponent(qm[1].replace(/\+/g,' ')) : '';
  const wantTokens = new Set(norm(wantName).split(' ').filter(Boolean));
  const wantLast = [...wantTokens].pop();

  const entries = text.split("<entry>").slice(1);
  for (const e of entries) {
    const g=(t)=>{const m=e.match(new RegExp("<"+t+"[^>]*>([\\s\\S]*?)</"+t+">"));return m?m[1].trim():"";};
    const idUrl=g("id"); const m=idUrl.match(/abs\/([^v]+)(v\d+)?/); const arxiv=m?m[1]:null;
    const title=g("title").replace(/\s+/g," "); const abstract=g("summary").replace(/\s+/g," ");
    const pub=g("published").slice(0,10);
    const names=[...e.matchAll(/<name[^>]*>([\s\S]*?)<\/name>/g)].map(x=>x[1].trim());

    let ok = !wantLast; // if we couldn't parse a name, don't over-filter
    if(wantLast){
      for(const nm of names){
        const nt=new Set(norm(nm).split(' ').filter(Boolean));
        if(!nt.has(wantLast)) continue;
        let sh=0; for(const t of wantTokens) if(nt.has(t)) sh++;
        if(sh>=Math.min(2,wantTokens.size)){ ok=true; break; }
      }
    }
    if(!ok) continue;

    const dedup_key = arxiv?`arxiv:${arxiv}`:`arxivurl:${idUrl}`;
    out.push({json:{dedup_key,arxiv_id:arxiv,doi:null,semantic_scholar_id:null,
      title,authors:names.join(", "),abstract,url:idUrl,
      pdf_url:arxiv?`https://arxiv.org/pdf/${arxiv}`:null,published_at:pub,
      venue:"arXiv",source:`arxiv_author:${wantName||'unknown'}`,min_score:minScore}});
  }
}
return out;

const items = $input.all().map(i=>i.json);
const map = new Map();
for (const p of items) {
  const k = p.dedup_key;
  const cur = map.get(k);
  if (!cur) { map.set(k,p); continue; }
  // keep the one with the longer abstract; tie-break: prefer one with pdf_url
  const a=(p.abstract||"").length, b=(cur.abstract||"").length;
  if (a>b || (a===b && p.pdf_url && !cur.pdf_url)) {
    // preserve richest ids by merging
    map.set(k, { ...cur, ...p,
      arxiv_id:p.arxiv_id||cur.arxiv_id, doi:p.doi||cur.doi,
      semantic_scholar_id:p.semantic_scholar_id||cur.semantic_scholar_id,
      pdf_url:p.pdf_url||cur.pdf_url,
      source: cur.source+"+"+p.source,
      min_score: Math.min(p.min_score, cur.min_score) });  // if followed-author on either side, use lower bar
  } else {
    map.set(k, { ...cur, source: cur.source+"+"+p.source,
      min_score: Math.min(p.min_score, cur.min_score) });
  }
}
// tag freshness instead of dropping: papers with a valid in-window date are
// 'fresh'; papers missing a date (or older) are kept but ranked last, so they
// only fill a topic when there aren't enough fresh papers.
const daysBack = $('Load Config').first().json.daysBack;
const cutoff = new Date(Date.now() - daysBack*864e5);
return [...map.values()].map(p => {
  const d = p.published_at ? new Date(p.published_at) : null;
  const _fresh = !!(d && !isNaN(d) && d >= cutoff);
  return { json: { ...p, _fresh } };
});

return $input.all().map(item=>{
  const p=item.json;
  const prompt = `Title: ${p.title}\nVenue: ${p.venue}\nAbstract: ${p.abstract}`;
  return { json: { ...p, prompt } };
});

