const papers = $('Build Filter Prompt').all();
return $input.all().map((item,i)=>{
  const paper = papers[i].json;
  let parsed={relevance:0,topic:"other",reason:"",should_read_full_paper:false};
  try { parsed=JSON.parse(item.json.choices[0].message.content); }
  catch(e){ parsed.reason="parse error"; }
  return { json:{ ...paper, relevance_score:parsed.relevance,
    reason_relevant:parsed.reason, should_read:parsed.should_read_full_paper, topic:parsed.topic||"other" }};
});

