const papers = $('Select Top 5 Per Topic').all();
function q(v){ // SQL string literal or NULL
  if(v===null||v===undefined||v==="") return "NULL";
  return "'" + String(v).replace(/'/g,"''") + "'";
}
function num(v){ return (v===null||v===undefined||v==="") ? "NULL" : Number(v); }
function dt(v){ // published_at -> date or NULL; only accept YYYY-MM-DD-ish
  if(!v) return "NULL";
  const m=String(v).match(/^\d{4}-\d{2}-\d{2}/);
  return m ? "'"+m[0]+"'" : "NULL";
}
return $input.all().map((item,i)=>{
  const paper=papers[i].json;
  let summary="";
  try{ summary=item.json.choices[0].message.content; }catch(e){ summary="(không tóm tắt được)"; }
  const cols=[
    q(paper.dedup_key), q(paper.arxiv_id), q(paper.doi), q(paper.semantic_scholar_id),
    q(paper.title), q(paper.authors), q(paper.abstract), q(paper.url), q(paper.pdf_url),
    dt(paper.published_at), q(paper.venue), num(paper.relevance_score),
    q(summary), q(paper.reason_relevant), q(paper.source)
  ].join(", ");
  const sql = `INSERT INTO papers
  (dedup_key, arxiv_id, doi, semantic_scholar_id, title, authors, abstract, url, pdf_url, published_at, venue, relevance_score, summary, reason_relevant, source, status)
VALUES (${cols}, 'new')
ON CONFLICT (dedup_key) DO NOTHING;`;
  return { json: { ...paper, summary, _sql: sql } };
});

const papers = $('Parse Summary').all().map(i=>i.json);
const isAuthor = p => (p.source||"").includes("author");
const bucket = p => { const t=(p.topic||"other").toLowerCase(); return (t==="quant"||t==="xai")?t:"other"; };
const groups = { quant:[], xai:[] };
for (const p of papers){ const b=bucket(p); if(groups[b]) groups[b].push(p); }
const sections=[{label:"⚙️ QUANTIZATION",items:groups.quant},{label:"🔍 EXPLAINABLE AI",items:groups.xai}];
const out=[];
for(const sec of sections){
  if(!sec.items.length) continue;
  out.push({json:{content:`**━━━ ${sec.label} ━━━**`}});
  sec.items.forEach((p,i)=>{
    const tag=isAuthor(p)?" 👤follow":"";
    let content=`📄 **${i+1}. ${p.title}** (score: ${p.relevance_score}${tag})\n`;
    content+=`🏛️ ${p.venue} · 🔗 ${p.url}\n\n${p.summary||'(no summary)'}`;
    if(content.length>1900) content=content.slice(0,1900)+"…";
    out.push({json:{content}});
  });
}
return out;

// cut to top 5 per topic BEFORE summarizing (saves tokens; DB stores only these)
const items = $input.all().map(i=>i.json);
const isAuthor = p => (p.source||"").includes("author");
const bucket = p => { const t=(p.topic||"other").toLowerCase(); return (t==="quant"||t==="xai")?t:"other"; };
const groups = { quant:[], xai:[] };
for (const p of items){ const b=bucket(p); if(groups[b]) groups[b].push(p); }
function pick5(arr){
  return arr.sort((a,b)=>{
    // 1) followed-author beats keyword hit
    const ap=isAuthor(a)?0:1, bp=isAuthor(b)?0:1;
    if(ap!==bp) return ap-bp;
    // 2) fresh (valid in-window date) beats stale/undated
    const af=a._fresh?0:1, bf=b._fresh?0:1;
    if(af!==bf) return af-bf;
    // 3) higher relevance score
    return (b.relevance_score||0)-(a.relevance_score||0);
  }).slice(0,5);
}
return [...pick5(groups.quant), ...pick5(groups.xai)].map(json=>({json}));
